PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (SUM(?oilC * ?pct / 100) AS ?total) WHERE {
  { SELECT ?c (SUM(?oil) AS ?oilC) WHERE {
      ?p a energia:WellProduction ; energia:inConcession ?c ; energia:oil ?oil .
    } GROUP BY ?c }
  { SELECT ?c (SUM(?pc) AS ?pct) WHERE {
      ?s a energia:Stake ; energia:inConcession ?c ; energia:partner ?co ; energia:percent ?pc .
      { SELECT DISTINCT ?co WHERE {
          ?co a energia:Company ; energia:name ?n .
          FILTER(STRSTARTS(UCASE(STR(?n)), "YPF"))
      } }
    } GROUP BY ?c }
}
